import{_ as i,l as o,o as e,c as n,v as t,p as l,x as r,d,i as h,S as E}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"无共享对共享存储","description":"","frontmatter":{"title":"无共享对共享存储","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/shared-nothing-vs-disk.md","filePath":"cs/shared-nothing-vs-disk.md","lastUpdated":1789023840000}'),p={name:"cs/shared-nothing-vs-disk.md"};function c(A,a,_,B,f,u){const s=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="无共享对共享存储" tabindex="-1">无共享对共享存储 <a class="header-anchor" href="#无共享对共享存储" aria-label="Permalink to &quot;无共享对共享存储&quot;">​</a></h1><div class="epigraph"><p>无共享：每节点私有盘，扩展靠网络 shuffle。共享磁盘：多节点挂同一存储，扩展靠缓存一致性与锁，故障切换快。</p><footer>—— 据 DeWitt and Gray 并行库分类；Stonebraker shared-nothing；Oracle RAC 点名</footer></div><p><a href="/cs/db-consistent-hashing">上一课</a>在环上放键。本课不谈令牌。缺口是经典三分法里的两极（共享内存较少作今日主路径）：shared-nothing vs shared-disk。决定故障域、扩展曲线、以及下一课存算能否分离。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无共享：MPP、大多数 NewSQL、Postgres 单机+分片中间件。节点挂则其数据要副本才可服务。扩展加机器加盘。共享磁盘：多机可开同一库文件，缓存融合（cache fusion）传页，分布式锁管理器（DLM）代单机 latch+lock 的一部分。缺口是<strong>争用</strong>：共享盘上写同一页要跨机锁，热点差；无共享把热点变成单节点但扩展线性较好。</p><p>恢复：共享盘可把计算挂到另一机立刻看到盘（要锁与缓存重建）；无共享要副本升主。</p><p><span class="marginnote">DeWitt and Gray CACM 并行数据库。Stonebraker 主张 shared-nothing。RAC 是共享盘代表。本课分类，不选型广告。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分析 MPP 常无共享+shuffle。OLTP 集群共享盘图省分片，但要买 DLM。云盘可被多挂，像共享盘，延迟与 IO 隔离是新问题——下一课分离。</p><p>分片键在无共享是必须；共享盘可先不分片。</p>',10)),(e(),l(E,null,{default:r(()=>[h(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SN%5B%22%E6%97%A0%E5%85%B1%E4%BA%AB%22%5D%20--%3E%20NET%5B%22%E7%BD%91%E7%BB%9C%E6%90%AC%E6%95%B0%E6%8D%AE%22%5D%0A%20%20SN%20--%3E%20REP%5B%22%E7%94%A8%E5%89%AF%E6%9C%AC%E6%8A%97%E8%8A%82%E7%82%B9%E6%95%85%E9%9A%9C%22%5D%0A%20%20SD%5B%22%E5%85%B1%E4%BA%AB%E7%A3%81%E7%9B%98%22%5D%20--%3E%20DLM%5B%22%E5%88%86%E5%B8%83%E5%BC%8F%E9%94%81%E4%B8%8E%E7%BC%93%E5%AD%98%E8%9E%8D%E5%90%88%22%5D%0A%20%20SD%20--%3E%20FAIL%5B%22%E8%AE%A1%E7%AE%97%E6%8D%A2%E6%9C%BA%E3%80%81%E7%9B%98%E4%BB%8D%E5%9C%A8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>代价模型：无共享连接计网络；共享盘计跨机页运。2Q 在共享盘要考虑被别的节点偷页。WAL：共享盘上日志设备也共享，组提交争用。</p><p>一致性哈希落在无共享上自然；共享盘用哈希分区仍可，但是可选。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲存算分离的对象存储。也不把无共享当「无状态」。HTAP 可能一侧无共享列存。</p><p>后课默认：MPP 无共享；传统集群共享盘存在。存算分离：计算无状态、存储多租户服务化。</p><p>分类决定故障时搬计算还是搬数据。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无共享扩盘与计算绑定，靠副本；共享盘换计算快、写争用高。</li><li>连接与锁的代价项因此不同。</li><li>存算分离下一课。</li><li>出处：DeWitt and Gray；Stonebraker；RAC 实践。</li></ul>',9))])}const P=i(p,[["render",c]]);export{m as __pageData,P as default};
